[package]
name = "spotatui"
description = "Terminal music player for Spotify, local files, Subsonic, radio, YouTube, Qobuz"
homepage = "https://spotatui.com"
documentation = "https://github.com/LargeModGames/spotatui/tree/main/docs"
repository = "https://github.com/LargeModGames/spotatui"
keywords = ["music-player", "spotify", "tui", "terminal", "music"]
categories = ["command-line-utilities", "multimedia::audio"]
version = "0.46.0"
authors = ["LargeModGames <LargeModGames@gmail.com>"]
edition = "2021"
rust-version = "1.90"
license = "MIT"
# Two [[bin]] targets make a plain `cargo run` ambiguous; the console binary
# stays the default.
default-run = "spotatui"
exclude = [
    ".github/demo.gif",
    ".github/workflows",
    ".github/ISSUE_TEMPLATE",
    "target/",
    "/gui/",
]

# See more keys and their definitions at https://doc.rust-lang.org/cargo/reference/manifest.html

[dependencies]
rspotify = { version = "0.16", default-features = false, features = ["cli", "env-file", "client-reqwest", "reqwest-rustls-tls"] }
ratatui = { version = "0.30", features = ["crossterm", "layout-cache"], default-features = false, optional = true }
serde = { version = "1.0", features = ["derive"] }
serde_json = "1.0"
serde_yaml = "0.9"
dirs = "7.0"
clap = { version = "4.6", features = ["cargo"] }
clap_complete = "4.6"
unicode-width = "0.2.2"
backtrace = "0.3.76"
crossterm = { version = "0.29", optional = true }
tui-bar-graph = { version = "0.3.3", optional = true }
# Optional because the headless build needs neither half of it: `tui` pulls it
# for the banner gradient and visualizer, `art-decode` for the HSV math in
# `core/cover_theme.rs`.
colorgrad = { version = "0.8.0", optional = true }
tokio = { version = "1.52", features = ["full"] }
rand = "0.10.2"
anyhow = "1.0.102"
chrono = "0.4.45"
log = "0.4.32"
fern = "0.7.1"
open = "5.3"
self_update = { version = "0.44", features = ["archive-tar", "archive-zip", "compression-flate2", "compression-zip-deflate"], optional = true }
sha2 = { version = "0.11", optional = true }
hex = { version = "0.4", optional = true }
reqwest = { version = "0.12", features = ["json", "rustls-tls", "blocking"], default-features = false }
openssl = { version = "0.10", optional = true }
cpal = { version = "0.17", optional = true }
realfft = { version = "3.4", optional = true }
discord-rich-presence = { version = "1.1", optional = true }
ratatui-image = { version = "11.0.4", optional = true, default-features = false, features = ["crossterm"] }
image = { version = "0.25", optional = true }
mlua = { version = "0.12", features = ["lua54", "vendored", "serde"], optional = true }
md-5 = { version = "0.11", optional = true }
# Subsonic, YouTube and Qobuz stream each track to a tempfile before playing it through the shared
# rodio sink. Also a dev-dependency (used by tests across features).
tempfile = { version = "3", optional = true }
# Qobuz transport: the signed-request and key-derivation primitives plus the
# bundle scrape. Same `cipher 0.4` line as librespot, so no graph fork.
base64 = { version = "0.23", optional = true }
regex = { version = "1", optional = true }
aes = { version = "0.8", optional = true }
cbc = { version = "0.1", optional = true }
ctr = { version = "0.9", optional = true }
hkdf = { version = "0.13", optional = true }
# Qobuz progressive delivery: the chunk type of a stream-download source.
bytes = { version = "1", optional = true }

# stream-download buffers a byte stream behind a Read+Seek adapter that rodio
# can decode while the download runs. Internet radio uses it on an infinite HTTP
# (ICY) stream, without seeking; Qobuz uses it on its segment transport, with
# seeking. icy-metadata parses in-band StreamTitle now-playing metadata and is
# only compiled under the opt-in `internet-radio` feature.
stream-download = { version = "0.24", optional = true, default-features = false, features = ["reqwest-rustls"] }
icy-metadata = { version = "0.6", optional = true, default-features = false }

# Local-files media source dependencies
symphonia = { version = "0.6", features = ["mp3", "flac", "ogg", "wav", "aiff", "isomp4", "mkv", "pcm", "vorbis"], optional = true, default-features = false }
lofty = { version = "0.25", optional = true }
# Local-files audio output. Defaults pull in cpal `playback` plus the common
# codecs (flac/mp3/mp4-aac/vorbis/wav) via symphonia. Drives the default device
# on all three platforms; the macOS gate in `LocalPlayer` is gone since rodio
# 0.22 / cpal 0.17 were measured on CoreAudio. Unrelated to librespot's own
# rodio-backend, which is why librespot keeps portaudio-backend on macOS.
rodio = { version = "0.22", optional = true }

# Streaming dependencies: our maintained librespot fork, published on crates.io
# as spotatui-librespot-* (upstream 0.8.0 + CDN 530 fallback for silent playback,
# dealer reconnect/session-loss recovery, OAuth callback listener hardening,
# previous-on-first-track restarting instead of stopping (#366), Spirc ignoring
# play-request ids
